1	import 'package:flutter_test/flutter_test.dart';
2	import 'package:fpdart/fpdart.dart';
3	import 'package:mocktail/mocktail.dart';
4	
5	import 'package:cerne/core/failure/failure.dart';
6	import 'package:cerne/core/resource.dart';
7	import 'package:cerne/features/auth/domain/entities/authenticated_user.dart';
8	import 'package:cerne/features/auth/domain/repositories/auth_repository.dart';
9	import 'package:cerne/features/auth/presentation/cubit/auth_cubit.dart';
10	import 'package:cerne/features/auth/presentation/cubit/auth_state.dart';
11	
12	class MockAuthRepository extends Mock implements AuthRepository {}
13	
14	/// Collects every state the cubit emits for the duration of [act], since the
15	/// stack has no `bloc_test` pin — this drives [AuthCubit] through its public
16	/// API only (never the `@protected` `emit`), the same way any other
17	/// `flutter_bloc` consumer would.
18	Future<List<AuthState>> _emittedDuring(
19	  AuthCubit cubit,
20	  Future<void> Function() act,
21	) async {
22	  final emitted = <AuthState>[];
23	  final subscription = cubit.stream.listen(emitted.add);
24	  await act();
25	  // `submit()`'s awaited repository call resolves its mocked Future on a
26	  // microtask; `Future.delayed(Duration.zero)` only resumes once the whole
27	  // microtask queue (including the stream's event dispatch to our
28	  // listener) has drained, so this reliably waits for every emit `act()`
29	  // triggered before we stop listening.
30	  await Future<void>.delayed(Duration.zero);
31	  await subscription.cancel();
32	  return emitted;
33	}
34	
35	void main() {
36	  late MockAuthRepository mockAuthRepository;
37	
38	  setUp(() {
39	    mockAuthRepository = MockAuthRepository();
40	  });
41	
42	  group('AuthCubit — mode toggle', () {
43	    test(
44	      'toggleMode flips login <-> signUp, keeping typed field values',
45	      () async {
46	        final cubit = AuthCubit(mockAuthRepository);
47	        cubit.emailChanged('a@b.com');
48	        cubit.passwordChanged('segredo');
49	
50	        final emitted = await _emittedDuring(
51	          cubit,
52	          () async => cubit.toggleMode(),
