32	
33	  const secureStorageChannel = MethodChannel(
34	    'plugins.it_nomads.com/flutter_secure_storage',
35	  );
36	  final fakeNativeStorage = <String, String>{};
37	
38	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
39	    final args = call.arguments as Map<dynamic, dynamic>;
40	    switch (call.method) {
41	      case 'write':
42	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
43	        return null;
44	      case 'read':
45	        return fakeNativeStorage[args['key'] as String];
46	      case 'delete':
47	        fakeNativeStorage.remove(args['key'] as String);
48	        return null;
49	      case 'containsKey':
50	        return fakeNativeStorage.containsKey(args['key'] as String);
51	      default:
52	        return null;
53	    }
54	  }
