124	          .thenAnswer((_) => Stream.value(SessionStatus.authenticated));
125	
126	      sl.unregister<SessionRepository>();
127	      sl.registerLazySingleton<SessionRepository>(() => mockSessionRepository);
128	
129	      await tester.pumpWidget(const CerneApp());
130	      await tester.pumpAndSettle();
131	
